  const pending = await queuedCount();
  if (pending) return status(`${pending} change(s) pending`);
  status('checking…');
  try {
    const r = await pull();
    status(r.empty ? 'repo is empty'
      : r.unchanged ? 'in sync'
      : `in sync — ${r.changed} file(s) updated`);
  } catch (err) {
    status(err.message, true);
  }
}

